import 'package:family_veda/models/record_summary_meta.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/providers/records_provider.dart';
import 'package:family_veda/widgets/records/report_attachment_field.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class RecordEntryScreen extends ConsumerStatefulWidget {
  const RecordEntryScreen({super.key});

  @override
  ConsumerState<RecordEntryScreen> createState() => _RecordEntryScreenState();
}

class _RecordEntryScreenState extends ConsumerState<RecordEntryScreen> {
  final _formKey = GlobalKey<FormState>();
  String _type = 'Condition';
  String _status = '';
  String _severity = '';
  String _doctor = '';
  ReportAttachment? _attachment;
  bool _saving = false;
  String? _message;
  final _title = TextEditingController();
  final _summary = TextEditingController();
  // Local calendar day; the UTC day is a day behind before 05:30 in Sri Lanka.
  final _date = TextEditingController(text: _localDate(DateTime.now()));

  static String _localDate(DateTime value) =>
      '${value.year}-${value.month.toString().padLeft(2, '0')}-${value.day.toString().padLeft(2, '0')}';

  /// Assigned family doctor first, then the directory; names only, used as a label on the record.
  List<String> _doctorNames() {
    final assigned = ref.watch(familyDashboardProvider).valueOrNull?.familyDoctor;
    final directory = ref.watch(doctorDirectoryProvider).valueOrNull ?? const [];
    return {
      if (assigned != null) assigned.displayName,
      ...directory.map((doctor) => doctor.displayName),
    }.toList(growable: false);
  }

  DropdownButtonFormField<String> _optionalChoice({
    required String label,
    required String value,
    required List<String> options,
    required ValueChanged<String> onChanged,
  }) => DropdownButtonFormField<String>(
    initialValue: value,
    isExpanded: true,
    decoration: InputDecoration(labelText: label),
    items: [
      const DropdownMenuItem(value: '', child: Text('Not specified')),
      for (final option in options) DropdownMenuItem(value: option, child: Text(option)),
    ],
    onChanged: (selected) => onChanged(selected ?? ''),
  );

  @override
  void dispose() {
    _title.dispose();
    _summary.dispose();
    _date.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Add health record')),
    body: SafeArea(
      child: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            DropdownButtonFormField<String>(
              initialValue: _type,
              decoration: const InputDecoration(labelText: 'Record type *'),
              items: const ['Condition', 'Allergy', 'Medication', 'Surgery', 'Note']
                  .map((value) => DropdownMenuItem(value: value, child: Text(value)))
                  .toList(),
              onChanged: (value) => _type = value ?? 'Condition',
            ),
            TextFormField(
              controller: _title,
              decoration: const InputDecoration(labelText: 'Title *'),
              maxLength: 160,
              validator: (value) => value == null || value.trim().length < 2 ? 'Enter a title.' : null,
            ),
            TextFormField(
              controller: _date,
              decoration: const InputDecoration(labelText: 'Date (YYYY-MM-DD) *'),
              validator: (value) => DateTime.tryParse(value ?? '') == null ? 'Enter a valid date.' : null,
            ),
            _optionalChoice(
              label: 'Status',
              value: _status,
              options: RecordSummaryMeta.statuses,
              onChanged: (value) => _status = value,
            ),
            _optionalChoice(
              label: 'Severity',
              value: _severity,
              options: RecordSummaryMeta.severities,
              onChanged: (value) => _severity = value,
            ),
            _optionalChoice(
              label: 'Doctor / Healthcare Provider',
              value: _doctor,
              options: _doctorNames(),
              onChanged: (value) => _doctor = value,
            ),
            TextFormField(
              controller: _summary,
              decoration: const InputDecoration(labelText: 'Summary'),
              maxLength: 2000,
              maxLines: 3,
            ),
            ReportAttachmentField(
              attachment: _attachment,
              enabled: !_saving,
              onChanged: (value) => setState(() {
                _attachment = value;
                _message = null;
              }),
              onError: (message) => setState(() => _message = message),
            ),
            const SizedBox(height: 16),
            FilledButton(onPressed: _saving ? null : _save, child: Text(_saving ? 'Saving…' : 'Save record')),
            if (_message != null) ...[const SizedBox(height: 16), Text(_message!)],
          ],
        ),
      ),
    ),
  );

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    final memberId = ref.read(activeMemberProvider);
    if (memberId == null) {
      setState(() => _message = 'Select an active member first.');
      return;
    }
    setState(() {
      _saving = true;
      _message = null;
    });
    try {
      await ref.read(mobileApiProvider).addRecord(
        memberId: memberId,
        recordType: _type,
        title: _title.text,
        summary: RecordSummaryMeta(
          status: _status,
          severity: _severity,
          doctor: _doctor,
          cleanSummary: _summary.text,
        ).format(),
        occurredOn: DateTime.parse(_date.text),
      );
      ref.invalidate(memberRecordsProvider);
    } catch (_) {
      if (mounted) setState(() => _message = 'Record could not be saved. Check the connection and try again.');
      return;
    } finally {
      if (mounted) setState(() => _saving = false);
    }
    await _uploadAttachment(memberId);
  }

  /// The record is already saved here, so the screen closes either way and a failed upload is reported.
  Future<void> _uploadAttachment(String memberId) async {
    if (!mounted) return;
    final attachment = _attachment;
    if (attachment == null) {
      Navigator.of(context).pop();
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _saving = true);
    try {
      await ref.read(mobileApiProvider).uploadLabReport(memberId: memberId, path: attachment.path);
      ref.invalidate(memberLabReportsProvider);
    } catch (_) {
      messenger.showSnackBar(
        const SnackBar(
          content: Text(
            'Record saved, but the attached report could not be uploaded. Add it from Upload lab report.',
          ),
        ),
      );
    }
    if (mounted) Navigator.of(context).pop();
  }
}
